changeSet.sql:
INSERT INTO stretchy_report_parameter(report_id, parameter_id, report_parameter_name, mandatory_parameter) SELECT r.id, p.id, 'transactionTypeSavings', TRUE FROM stretchy_report r JOIN stretchy_parameter p ON p.parameter_name = 'transactionTypeSavings' WHERE r.report_name = 'Journal Entries For Savings';
INSERT INTO stretchy_report_parameter(report_id, parameter_id, report_parameter_name, mandatory_parameter) SELECT r.id, p.id, 'startDate', TRUE FROM stretchy_report r JOIN stretchy_parameter p ON p.parameter_name = 'startDateSelect' WHERE r.report_name = 'Journal Entries For Savings';
INSERT INTO stretchy_report_parameter(report_id, parameter_id, report_parameter_name, mandatory_parameter) SELECT r.id, p.id, 'endDate', TRUE FROM stretchy_report r JOIN stretchy_parameter p ON p.parameter_name = 'endDateSelect' WHERE r.report_name = 'Journal Entries For Savings';
INSERT INTO stretchy_report_parameter(report_id, parameter_id, report_parameter_name, mandatory_parameter) SELECT r.id, p.id, 'transactionTypeLoan', TRUE FROM stretchy_report r JOIN stretchy_parameter p ON p.parameter_name = 'transactionTypeLoan' WHERE r.report_name = 'Journal Entries For Loan';
INSERT INTO stretchy_report_parameter(report_id, parameter_id, report_parameter_name, mandatory_parameter) SELECT r.id, p.id, 'startDate', TRUE FROM stretchy_report r JOIN stretchy_parameter p ON p.parameter_name = 'startDateSelect' WHERE r.report_name = 'Journal Entries For Loan';
INSERT INTO stretchy_report_parameter(report_id, parameter_id, report_parameter_name, mandatory_parameter) SELECT r.id, p.id, 'endDate', TRUE FROM stretchy_report r JOIN stretchy_parameter p ON p.parameter_name = 'endDateSelect' WHERE r.report_name = 'Journal Entries For Loan';
